?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Učíme se IT | Výukové aplikace</title><link rel="stylesheet" href="style.css"></head><body><header><div class="wrap top"><a class="logo" href="/">&lt;/&gt; Učíme se IT</a><a class="adminlink" href="admin.php">Administrace</a></div></header><main class="wrap"><div class="hero"><span class="eyebrow">VÝUKOVÝ PORTÁL</span><h1>Učení prakticky.</h1><p>Vyber si téma a otevři interaktivní cvičení.</p></div><div class="section"><h2>Výukové aplikace</h2><span><?=count($items)?> témat</span></div><?php foreach($groups as $category=>$groupItems): ?><section class="subject-block"><div class="section"><h2><?=e($category!==''?$category:'Nezařazené')?></h2><span><?=count($groupItems)?> aplikací</span></div><div class="grid"><?php foreach($groupItems as $i=>$item): ?><a class="tile" href="https://ucimeseit.cz/ucebnice/<?=rawurlencode($item['slug'])?>/"><span class="symbol"><?=e($item['icon']??'⌘')?></span><span class="num">TÉMA <?=str_pad($i+1,2,'0',STR_PAD_LEFT)?></span><h3><?=e($item['title'])?></h3><p><?=e($item['description']??'Otevřít výukovou aplikaci')?></p><span class="go">Otevřít aplikaci →</span></a><?php endforeach; ?></div></section><?php endforeach; ?></main><footer class="wrap">Učíme se IT · Výukové materiály a interaktivní aplikace</footer></body></html>
